// Passive observations only. Envelopes are geometric opportunities, not solids.
import {withPhysicsTrace} from '../physics/passive-trace.js';
import {canonicalJSON} from './pin-layout-model.js';
export const FEED_DIAGNOSIS=Object.freeze({schema:'s8-feed-diagnosis-v1',centre:{x:64,y:476.5},rotorRadius:Math.hypot(9.5,.35),legacyRadius:11.3,roi:{minX:20,maxX:100,minY:390,maxY:500},gate:{sourceY:713,leftBelow:136,rightAbove:176},phase:0});
const isWheel=part=>part.kind==='windmill-photo-three-vane'||part.kind==='windmill-arm';
export function contactChange(before,after){const position=before.x!==after.x||before.y!==after.y,velocity=before.vx!==after.vx||before.vy!==after.vy;return position&&velocity?'both':position?'position-only':velocity?'velocity-only':'unchanged';}
export function nearestMotion(before,after,centre=FEED_DIAGNOSIS.centre){const dx=after.x-before.x,dy=after.y-before.y,length=dx*dx+dy*dy,fraction=length?Math.max(0,Math.min(1,((centre.x-before.x)*dx+(centre.y-before.y)*dy)/length)):0,x=before.x+fraction*dx,y=before.y+fraction*dy;return {distance:Math.hypot(x-centre.x,y-centre.y),fraction,x,y};}
export function envelopeCrossings(before,after,radius,centre=FEED_DIAGNOSIS.centre){const dx=after.x-before.x,dy=after.y-before.y,x=before.x-centre.x,y=before.y-centre.y,a=dx*dx+dy*dy;if(!a)return [];const b=2*(x*dx+y*dy),c=x*x+y*y-radius*radius,disc=b*b-4*a*c;if(disc<0)return [];return [...new Set([(-b-Math.sqrt(disc))/(2*a),(-b+Math.sqrt(disc))/(2*a)])].filter(t=>t>0&&t<=1).sort((a,b)=>a-b).map(fraction=>({fraction,direction:(x+fraction*dx)*dx+(y+fraction*dy)*dy<0?'enter':'exit'}));}
export function compareFeedOracle(current,old){const body=r=>{const copy={...r};for(const k of ['sourceSHA','planSHA','caseManifestSHA'])delete copy[k];return canonicalJSON(JSON.parse(JSON.stringify(copy)));};return {exact:body(current)===body(old),currentCanonical:body(current),oldCanonical:body(old),excludedFields:['sourceSHA','planSHA','caseManifestSHA']};}
export function createFeedCollector(sink=()=>{}){
 const balls=new Map(),get=id=>{if(!Number.isSafeInteger(id)||id<1)throw Error('Invalid trace ball ID');if(!balls.has(id))balls.set(id,{ballId:id,pointMinimum:null,motionMinimum:null,envelopeFirst:{current:null,legacy:null},pinContacts:[],windmillContacts:[],lastApproachContact:null,lastApproachReflection:null,outcome:null});return balls.get(id);};let sourceSeq=0,seq=0,substep=0,interval={timeStart:null,timeEnd:null,gameTime:null};const savedCounts={};
 const emit=row=>{const value={seq:++seq,...row};savedCounts[value.type]=(savedCounts[value.type]??0)+1;sink(structuredClone(value));return value;};
 const point=(p,time,origin)=>{const row=get(p.id);if(!p.front)return;const distance=Math.hypot(p.x-64,p.y-476.5);if(!row.pointMinimum||distance<row.pointMinimum.distance)row.pointMinimum={distance,time,origin,sourceSeq,substep,state:structuredClone(p)};};
 return {accept(e){sourceSeq++;if(e.type==='substep'){if(e.stage==='before'){substep++;interval={timeStart:e.timeStart,timeEnd:e.timeEnd,gameTime:e.gameTime};}for(const p of e.balls)point(p,e.stage==='before'?e.timeStart:e.timeEnd,`substep-${e.stage}`);return;}
  const context={sourceSeq,substep,...interval,...e};
  if(e.type==='motion'){
   point(e.before,e.timeStart,'motion-before');point(e.after,e.timeEnd,'motion-after');
   const roi=FEED_DIAGNOSIS.roi,near=Math.max(e.before.x,e.after.x)>=roi.minX&&Math.min(e.before.x,e.after.x)<=roi.maxX&&Math.max(e.before.y,e.after.y)>=roi.minY&&Math.min(e.before.y,e.after.y)<=roi.maxY;
   if(near)emit(context);
   if(e.before.front&&e.after.front){const row=get(e.before.id),closest=nearestMotion(e.before,e.after);if(!row.motionMinimum||closest.distance<row.motionMinimum.distance)row.motionMinimum={...closest,timeStart:e.timeStart,timeEnd:e.timeEnd,sourceSeq,substep,before:structuredClone(e.before),after:structuredClone(e.after),scope:'Actual single integration line only, not solver-correction interpolation'};
    for(const [name,base]of [['current',FEED_DIAGNOSIS.rotorRadius],['legacy',FEED_DIAGNOSIS.legacyRadius]]){const radius=base+e.before.r;if(closest.distance<=radius&&!row.envelopeFirst[name])row.envelopeFirst[name]={timeStart:e.timeStart,timeEnd:e.timeEnd,sourceSeq,radius,closest:structuredClone(closest),beforeInside:Math.hypot(e.before.x-64,e.before.y-476.5)<=radius};for(const crossing of envelopeCrossings(e.before,e.after,radius))emit({type:'envelope-cross',sourceSeq,substep,timeStart:e.timeStart,timeEnd:e.timeEnd,gameTime:e.gameTime,ballId:e.before.id,frontBefore:e.before.front,frontAfter:e.after.front,envelope:name,radius,...crossing,scope:'Non-solid envelope; finite actual motion segment'});}
   }
  }else if(e.type==='contact'){
   for(const p of [e.before,e.after,e.peerBefore,e.peerAfter])if(p)point(p,e.time,`contact-${e.part.kind}`);
   if(e.part.kind!=='pin'&&!isWheel(e.part))return;
   const row=get(e.before.id),change=contactChange(e.before,e.after),record=emit({...context,change});
   const item={seq:record.seq,sourceSeq,time:e.time,stage:e.stage,part:structuredClone(e.part),change,solverResult:e.solverResult,before:structuredClone(e.before),after:structuredClone(e.after)};
   if(e.part.kind==='pin'){row.pinContacts.push(item);if(e.part.id>=37&&e.part.id<=63){row.lastApproachContact=structuredClone(item);if(e.solverResult)row.lastApproachReflection=structuredClone(item);}}
   else row.windmillContacts.push({...item,precedingApproachContact:structuredClone(row.lastApproachContact),precedingApproachReflection:structuredClone(row.lastApproachReflection)});
  }else if(e.type==='outcome'){const row=get(e.ball.id);point(e.ball,e.time,'outcome');row.outcome={time:e.time,kind:e.outcome,state:structuredClone(e.ball)};emit(context);}
 },finish(result){
  const shots=result.events.filter(e=>e.type==='shot'),ids=new Set(shots.map(e=>e.ballId));if(ids.size!==shots.length||shots.length!==result.physical.shots)throw Error('Shot denominator mismatch');
  if([...balls.keys()].some(id=>!ids.has(id)))throw Error('Trace contains unknown ball');
  const observation=new Map(result.s8ShotObservation.rows.map(b=>[b.ballId,b]));
  for(const shot of shots){const row=get(shot.ballId),old=observation.get(shot.ballId);if(!old)throw Error('Missing existing observation');row.shotTime=shot.time;row.firstDescending=structuredClone(old.route.firstDescending);row.recordedSuccessfulWindmill=!!old.firstWindmillContact;row.successfulWindmill=row.windmillContacts.some(c=>!!c.solverResult);row.positionOnlyWindmill=row.windmillContacts.some(c=>c.change==='position-only');row.velocityChangingWindmill=row.windmillContacts.some(c=>c.change==='both'||c.change==='velocity-only');row.changedWindmill=row.windmillContacts.length>0;row.frontChangedWindmill=row.windmillContacts.some(c=>c.before.front&&c.after.front);row.frontSuccessfulWindmill=row.windmillContacts.some(c=>c.before.front&&c.after.front&&!!c.solverResult);row.backOrTransitionWindmill=row.windmillContacts.some(c=>!c.before.front||!c.after.front);row.outcomeKind=row.outcome?.kind??'remaining';if(row.successfulWindmill!==row.recordedSuccessfulWindmill)throw Error('Actual successful-contact/firstWindmill observation mismatch');const terminal=result.events.find(e=>e.type==='outcome'&&e.ballId===shot.ballId);if(terminal&&(!row.outcome||row.outcome.kind!==terminal.kind||row.outcome.time!==terminal.time))throw Error('Missing/mismatched trace terminal');row.finalRecordedState=structuredClone(row.outcome?.state??result.replayEndpoints?.end?.balls.find(b=>b.id===shot.ballId)??null);emit({type:'endpoint',ballId:shot.ballId,outcome:row.outcomeKind,time:row.outcome?.time??result.end.time,state:row.finalRecordedState,origin:row.outcome?'actual-outcome':'existing-exact-end-replay'});}
  const list=shots.map(s=>get(s.ballId)),counter=predicate=>list.filter(predicate).length;const counts={shots:list.length,successfulWindmill:counter(b=>b.successfulWindmill),noSuccessfulWindmill:counter(b=>!b.successfulWindmill),positionOnlyWindmill:counter(b=>b.positionOnlyWindmill),changedWindmill:counter(b=>b.changedWindmill),noChangedWindmill:counter(b=>!b.changedWindmill),velocityChangingWindmill:counter(b=>b.velocityChangingWindmill),frontChangedWindmill:counter(b=>b.frontChangedWindmill),frontSuccessfulWindmill:counter(b=>b.frontSuccessfulWindmill),backOrTransitionWindmill:counter(b=>b.backOrTransitionWindmill)};
  return {schema:FEED_DIAGNOSIS.schema,definitions:FEED_DIAGNOSIS,counts,savedCounts,records:seq,sourceRecordsObserved:sourceSeq,balls:structuredClone(list),scope:'All actual changed pin/windmill calls, including correction-only and repeated contacts. Contact counts include all recorded planes with explicit front-only counters. Point minima use all actual observed snapshots (not all are emitted in ROI trace); motion minima use only real pre-collider integration segments. Envelopes are not solids. No causal attribution from geometric entry.'};
 }};
}
export function withFeedDiagnosis(operation,sink){const collector=createFeedCollector(sink);let result;try{result=withPhysicsTrace(operation,e=>collector.accept(e));return {result,trace:collector.finish(result)};}catch(error){if(!error.result&&result)error.result=result;throw error;}}
